<?php
$u=sr_auth();$items=sr_all('SELECT * FROM notifications WHERE user_id=? ORDER BY id DESC LIMIT 100',[$u['id']]);
sr_page_heading('CẬP NHẬT','Thông báo của bạn','Các thay đổi quan trọng trong quá trình tuyển dụng và ứng tuyển.');
?><div class="toolbar"><span><strong><?=count($items)?></strong> thông báo gần đây</span><?php if($items):?><form method="post"><?=sr_token()?><input type="hidden" name="action" value="notification_read"><input type="hidden" name="all" value="1"><button class="button secondary sm">Đánh dấu tất cả đã đọc</button></form><?php endif;?></div>
<?php if(!$items):?><div class="panel empty-state"><h2>Chưa có thông báo</h2><p>Các cập nhật về ứng tuyển và tin tuyển dụng sẽ xuất hiện ở đây.</p></div><?php else:?><div class="panel notification-list"><?php foreach($items as $n):?><div class="notification <?=((int)$n['is_read']===0?'unread':'')?>"><span class="notification-dot"></span><div><p><?=h($n['content'])?></p><small><?=h(sr_date($n['created_at']))?></small></div><div class="notification-actions"><a class="text-link" href="<?=h($n['url'])?>">Xem →</a><?php if(!(int)$n['is_read']):?><form method="post"><?=sr_token()?><input type="hidden" name="action" value="notification_read"><input type="hidden" name="id" value="<?=$n['id']?>"><button class="button ghost xs">Đã đọc</button></form><?php endif;?></div></div><?php endforeach;?></div><?php endif;?>
